다음의 Java 소스 코드에 대하여 가장 적절한 클래스 다이어그램은?

public class Rectangle {
private int width, height; private int area; private static int count;
public Rectangle(int w, int h) {
setWidth(w); setHeight(h); count++;
}
public void setWidth(int w) {
this.width = w; area = width * height;
}
public void setHeight(int h) {
this.height = h; area = width * height;
}
}
